05-30.concept:
flowchart TD
    Q["query"] --> DEC{"does the model already know this?"}
    DEC -->|"no such classifier"| RET["retrieve anyway"]
    RET --> SUF{"context sufficient?"}
    SUF -->|yes| ANS["answer"]
    SUF -->|no| MORE["retrieve again / stop"]

04-9.concept:
flowchart TD
    L["agent wants another tool call"] --> D{"identical (tool, args) repeated?"}
    D -->|yes| STOP["stop: warn or abort"]
    D -->|no| CAP{"iteration cap reached?"}
    CAP -->|yes| STOP
    CAP -->|no| CONT["continue the loop"]

04-31.concept:
flowchart TD
    NEED["project needs"] --> GRAPH{"explicit graph / state machine?"}
    GRAPH -->|yes| LG["LangGraph"]
    GRAPH -->|no| ROLE{"role / team abstraction?"}
    ROLE -->|yes| CREW["CrewAI"]
    ROLE -->|no| SDK["provider SDK / lighter layer"]

04-44.concept:
flowchart TD
    A["agentic retrieval"] --> L{"need to retrieve again?"}
    L -->|no| ANS["answer"]
    L -->|yes| CAP{"hop / cost budget left?"}
    CAP -->|no| STOP["stop and answer"]
    CAP -->|yes| R["retrieve"]
